select r.professor_id, p.name as professor_name, p.department, p.title, count(r.record_id) as record_count, coalesce(sum(r.student_count), 0) as total_students, coalesce(sum(r.calculated_score), 0) as total_score from ms_teaching_record r left join ms_professor p on r.professor_id = p.professor_id
r.status = '0' and r.semester = #{_parameter}
