select r.professor_id, p.name as professor_name, count(case when r.is_research = '1' then 1 end) as research_count, coalesce(sum(case when r.is_research = '1' then r.calculated_score else 0 end), 0) as research_score, coalesce(sum(r.calculated_score), 0) as total_score from ms_teaching_record r left join ms_professor p on r.professor_id = p.professor_id
r.status = '0' and r.semester = #{_parameter}
group by r.professor_id, p.name order by research_score desc
